1	import { useEffect, useRef, useState } from "react";
2	import Sidebar from "./components/Sidebar";
3	import Composer from "./components/Composer";
4	import MessageView from "./components/MessageView";
5	import { ChevronDownIcon, SidebarIcon } from "./components/Icons";
6	import type { Conversation, Message } from "./types";
7	
8	const uid = () => Math.random().toString(36).slice(2, 10);
9	
10	const SEED: Conversation[] = [
11	  {
12	    id: "c1",
13	    title: "Explain React hooks",
14	    messages: [
15	      { id: "m1", role: "user", content: "Explain React hooks in simple terms." },
16	      {
17	        id: "m2",
18	        role: "assistant",
19	        content:
20	          "Hooks are functions that let you use state and other React features inside function components. useState stores values, useEffect runs side effects, and you can combine them into your own custom hooks.",
21	      },
22	    ],
23	  },
24	  { id: "c2", title: "Trip ideas for Japan", messages: [] },
25	  { id: "c3", title: "Write a cover letter", messages: [] },
26	];
27	
28	const SUGGESTIONS = ["Summarize a long article", "Help me write an email", "Plan a weekend trip", "Explain a tricky concept"];
29	
30	// Placeholder reply generator — swap for a real API call.
31	const fakeReply = (q: string) =>
32	  `This is a demo response to: "${q}". Connect this UI to a backend or model API to get real answers.`;
33	
34	export default function App() {
35	  const [conversations, setConversations] = useState<Conversation[]>(SEED);
36	  const [activeId, setActiveId] = useState<string | null>(null);
37	  const [sidebarOpen, setSidebarOpen] = useState(true);
38	  const [busy, setBusy] = useState(false);
39	  const timer = useRef<number | null>(null);
40	  const bottom = useRef<HTMLDivElement>(null);
41	
42	  const active = conversations.find((c) => c.id === activeId) ?? null;
43	  const hasMessages = !!active && active.messages.length > 0;
44	
45	  useEffect(() => {
46	    bottom.current?.scrollIntoView({ behavior: "smooth" });
47	  }, [active?.messages]);
48	
49	  useEffect(
50	    () => () => {
51	      if (timer.current) clearInterval(timer.current);
52	    },
53	    []
54	  );
55	
56	  const patch = (id: string, fn: (m: Message[]) => Message[]) =>
57	    setConversations((cs) => cs.map((c) => (c.id === id ? { ...c, messages: fn(c.messages) } : c)));
58	
59	  const stop = () => {
60	    if (timer.current) clearInterval(timer.current);
61	    timer.current = null;
62	    setBusy(false);
63	  };
64	
65	  const send = (text: string) => {
66	    const convId = activeId ?? uid();
67	    const userMsg: Message = { id: uid(), role: "user", content: text };
68	    if (!activeId) {
69	      const title = text.length > 32 ? text.slice(0, 32) + "…" : text;
70	      setConversations((cs) => [{ id: convId, title, messages: [userMsg] }, ...cs]);
71	      setActiveId(convId);
72	    } else {
73	      patch(convId, (m) => [...m, userMsg]);
74	    }
75	
76	    const replyId = uid();
77	    const full = fakeReply(text);
78	    let i = 0;
79	    setBusy(true);
80	    patch(convId, (m) => [...m, { id: replyId, role: "assistant", content: "" }]);
81	    timer.current = window.setInterval(() => {
82	      i += 2;
83	      patch(convId, (m) => m.map((x) => (x.id === replyId ? { ...x, content: full.slice(0, i) } : x)));
84	      if (i >= full.length) stop();
85	    }, 20);
86	  };
87	
88	  const newChat = () => {
89	    stop();
90	    setActiveId(null);
91	  };
92	
93	  const lastId = active?.messages[active.messages.length - 1]?.id;
94	
95	  return (
96	    <div className="app">
97	      <Sidebar
98	        open={sidebarOpen}
99	        conversations={conversations}
100	        activeId={activeId}
101	        onToggle={() => setSidebarOpen((o) => !o)}
102	        onNew={newChat}
103	        onSelect={(id) => {
104	          stop();
105	          setActiveId(id);
106	        }}
107	      />
108	      <main className="main">
109	        <header className="topbar">
110	          {!sidebarOpen && (
111	            <button className="icon-btn" onClick={() => setSidebarOpen(true)} aria-label="Open sidebar">
112	              <SidebarIcon />
113	            </button>
114	          )}
115	          <button className="model-btn">
116	            ChatGPT <ChevronDownIcon />
117	          </button>
118	        </header>
119	
120	        <div className="scroll">
121	          {hasMessages ? (
122	            <div className="thread">
123	              {active!.messages.map((m) => (
124	                <MessageView key={m.id} message={m} typing={busy && m.id === lastId && m.role === "assistant"} />
125	              ))}
126	              <div ref={bottom} />
127	            </div>
128	          ) : (
129	            <div className="empty">
130	              <h1>What can I help with?</h1>
131	            </div>
132	          )}
133	        </div>
134	
135	        {!hasMessages && (
136	          <div className="chips">
137	            {SUGGESTIONS.map((s) => (
138	              <button key={s} className="chip" onClick={() => send(s)}>
139	                {s}
140	              </button>
141	            ))}
142	          </div>
143	        )}
144	        <Composer busy={busy} onSend={send} onStop={stop} />
145	      </main>
146	    </div>
147	  );
148	}

